import{_ as p,a0 as o,w as l,s as h,ao as r,I as e,x as n,a1 as t,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const m=JSON.parse('{"title":"如何將 Debian Linux 中的默認的 Python 版本切換為替代版本 | LCTT x X-CMD","titleTemplate":false,"description":"如何將 Debian Linux 中的默認的 Python 版本切換為替代版本 | LCTT (201602) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何將 Debian Linux 中的默認的 Python 版本切換為替代版本 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何將 Debian Linux 中的默認的 Python 版本切換為替代版本 | LCTT (201602) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201602/20160126 How to change from default to alternative Python version on Debian Linux","title":"如何將 Debian Linux 中的默認的 Python 版本切換為替代版本","tag":"201602","desc":""},"relativePath":"201602/20160126 How to change from default to alternative Python version on Debian Linux.md","filePath":"[post].md"}'),d={name:"201602/20160126 How to change from default to alternative Python version on Debian Linux.md"};function g(u,s,c,b,y,k){const i=o("Link");return l(),h("div",null,[s[11]||(s[11]=r(`<h1 id="如何將-debian-linux-中的默認的-python-版本切換為替代版本" tabindex="-1">如何將 Debian Linux 中的默認的 Python 版本切換為替代版本 <a class="header-anchor" href="#如何將-debian-linux-中的默認的-python-版本切換為替代版本" aria-label="Permalink to “如何將 Debian Linux 中的默認的 Python 版本切換為替代版本”">​</a></h1><p>當你安裝 Debian Linux 時，安裝過程有可能同時為你提供多個可用的 Python 版本，因此係統中會存在多個 Python 的可執行二進制文件。你可以按照以下方法使用 <code>ls</code> 命令來查看你的系統中都有那些 Python 的二進制文件可供使用。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls /usr/bin/python*</span></span>
<span class="line"><span>/usr/bin/python  /usr/bin/python2  /usr/bin/python2.7  /usr/bin/python3  /usr/bin/python3.4  /usr/bin/python3.4m  /usr/bin/python3m</span></span></code></pre></div><p>執行如下命令查看默認的 Python 版本信息:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ python --version</span></span>
<span class="line"><span>Python 2.7.8</span></span></code></pre></div><p>###1、基於用户修改 Python 版本：</p><p>想要為某個特定用户修改 Python 版本，只需要在其 home 目錄下創建一個 <code>alias</code>(別名) 即可。打開該用户的 <code>~/.bashrc</code> 文件，添加新的別名信息來修改默認使用的 Python 版本。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias python=&#39;/usr/bin/python3.4&#39;</span></span></code></pre></div><p>一旦完成以上操作，重新登錄或者重新加載 <code>.bashrc</code> 文件，使操作生效。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ . ~/.bashrc</span></span></code></pre></div><p>檢查當前的 Python 版本。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ python --version</span></span>
<span class="line"><span>Python 3.4.2</span></span></code></pre></div><p>###2、 在系統級修改 Python 版本</p><p>我們可以使用 <code>update-alternatives</code> 來為整個系統更改 Python 版本。以 root 身份登錄，首先羅列出所有可用的 python 替代版本信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># update-alternatives --list python</span></span>
<span class="line"><span>update-alternatives: error: no alternatives for python</span></span></code></pre></div><p>如果出現以上所示的錯誤信息，則表示 Python 的替代版本尚未被 <code>update-alternatives</code> 命令識別。想解決這個問題，我們需要更新一下替代列表，將 <code>python2.7</code> 和 <code>python3.4</code> 放入其中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># update-alternatives --install /usr/bin/python python /usr/bin/python2.7 1</span></span>
<span class="line"><span>update-alternatives: using /usr/bin/python2.7 to provide /usr/bin/python (python) in auto mode</span></span>
<span class="line"><span># update-alternatives --install /usr/bin/python python /usr/bin/python3.4 2</span></span>
<span class="line"><span>update-alternatives: using /usr/bin/python3.4 to provide /usr/bin/python (python) in auto mode</span></span></code></pre></div><p><code>--install</code> 選項使用了多個參數用於創建符號鏈接。最後一個參數指定了此選項的優先級，如果我們沒有手動來設置替代選項，那麼具有最高優先級的選項就會被選中。這個例子中，我們為 <code>/usr/bin/python3.4</code> 設置的優先級為2，所以 <code>update-alternatives</code> 命令會自動將它設置為默認 Python 版本。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># python --version</span></span>
<span class="line"><span>Python 3.4.2</span></span></code></pre></div><p>接下來，我們再次列出可用的 Python 替代版本。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># update-alternatives --list python</span></span>
<span class="line"><span>/usr/bin/python2.7</span></span>
<span class="line"><span>/usr/bin/python3.4</span></span></code></pre></div><p>現在開始，我們就可以使用下方的命令隨時在列出的 Python 替代版本中任意切換了。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># update-alternatives --config python</span></span></code></pre></div><p><img src="http://linuxconfig.org/images/change-python-alternative-version-debian-linux.png" alt=""></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># python --version</span></span>
<span class="line"><span>Python 2.7.8</span></span></code></pre></div><p>###3、移除替代版本</p><p>一旦我們的系統中不再存在某個 Python 的替代版本時，我們可以將其從 <code>update-alternatives</code> 列表中刪除掉。例如，我們可以將列表中的 python2.7 版本移除掉。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># update-alternatives --remove python /usr/bin/python2.7</span></span>
<span class="line"><span>update-alternatives: removing manually selected alternative - switching python to auto mode</span></span>
<span class="line"><span>update-alternatives: using /usr/bin/python3.4 to provide /usr/bin/python (python) in auto mode</span></span></code></pre></div><hr>`,29)),e("p",null,[s[1]||(s[1]=n("via: ",-1)),t(i,{href:"http://linuxconfig.org/how-to-change-from-default-to-alternative-python-version-on-debian-linux"},{default:a(()=>[...s[0]||(s[0]=[n("http://linuxconfig.org/how-to-change-from-default-to-alternative-python-version-on-debian-linux",-1)])]),_:1})]),e("p",null,[s[4]||(s[4]=n("譯者：",-1)),t(i,{href:"https://github.com/mr-ping"},{default:a(()=>[...s[2]||(s[2]=[n("mr-ping",-1)])]),_:1}),s[5]||(s[5]=n(" 校對：",-1)),t(i,{href:"https://github.com/wxy"},{default:a(()=>[...s[3]||(s[3]=[n("wxy",-1)])]),_:1})]),e("p",null,[s[8]||(s[8]=n("本文由 ",-1)),t(i,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...s[6]||(s[6]=[n("LCTT",-1)])]),_:1}),s[9]||(s[9]=n(" 原創編譯，",-1)),t(i,{href:"https://linux.cn/"},{default:a(()=>[...s[7]||(s[7]=[n("Linux中國",-1)])]),_:1}),s[10]||(s[10]=n(" 榮譽推出",-1))])])}const x=p(d,[["render",g]]);export{m as __pageData,x as default};
